interface ResolutionSource { double metres(); }
class CentimetreResolution implements ResolutionSource {
    private final int centimetres = 5;
    public double metres() { return centimetres / 100.0; }
}
public class AbstractionMeaningDemo {
    public static void main(String[] args) {
        ResolutionSource source = new CentimetreResolution();
        System.out.println(source.metres());
    }
}
